"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4664],{77569:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SkillTreeData","desc":"Permanent coin-bought upgrade tree (the lobby SkillTree modal). Nodes form\\na radial skill tree: 3 themed branches wind out from a decorative hub,\\neach branch INTERLEAVING its stats round-robin (health, regen, health,\\nregen, \u2026) so a player can never max one stat without buying the tiers\\nof its branch-mates along the way. Each node grants +1 effect tier of\\nits stat and requires only the previous node in its branch (a pure\\nchain).\\n\\nOwned nodes persist in the profile (`skillNodes` map, string keys). The\\neffective permanent level of a stat is the count of owned nodes granting\\nit (see `statLevels`); the game applies the actual effect magnitudes.\\n\\nThe placeholder stats below are generic \u2014 a game forking this tree\\nreplaces `STATS` and `BRANCHES` with its own content. The schema (node\\nids, costs, prerequisites, layout) is the product.\\n\\nNode positions are canvas-scale coordinates for SkillTreeModal (they may\\nexceed 0..1 \u2014 the canvas is a coordinate space, panning reaches them);\\nlayout is generated here so the tree can be re-shaped in data alone.\\nNode ids stay `{stat}_{tier}`, so profiles survive topology changes.","source":{"line":28,"path":"src/Shared/Data/Upgrades/SkillTreeData.luau"}}')}}]);